title:
// 자막 변경
const changeCaptions = (player: any, language: string) => {
  const tracks = player.textTracks();
  for (let i = 0; i < tracks.length; i++) {
    const track = tracks[i];
    if (track.language === language) {
      track.mode = 'showing';
    } else {
      track.mode = 'hidden';
    }
  }
}

