const LoginForm = () => {
  const [error, setError] = useState("")

  return (
    <form>
      <div>
        <label htmlFor="email">이메일</label>
        <input
          id="email"
          type="email"
          aria-invalid={error ? "true" : "false"}
          aria-describedby={error ? "email-error" : undefined}
        />
        {error && (
          <p id="email-error" className="error-text" role="alert">
            올바른 이메일 형식이 아닙니다
          </p>
        )}
      </div>
    </form>
  )
}

