title:
const AutoplayVideo = () => {
  const [canPlay, setCanPlay] = useState(false)
  const videoRef = useRef<HTMLVideoElement>(null)

  const handlePlayClick = () => {
    setCanPlay(true)
    videoRef.current?.play()
  }

  return (
    <div>
      <video
        ref={videoRef}
        controls
        preload="metadata"
        autoPlay={false}
        aria-label="소개 영상"
      >
        <source src="video.mp4" type="video/mp4" />
      </video>

      {!canPlay && (
        <button
          onClick={handlePlayClick}
          aria-label="영상 재생하기"
        >
          재생하기
        </button>
      )}
    </div>
  )
}

