const Slider = () => {
  const [value, setValue] = useState(50)

  const handleKeyDown = (e: React.KeyboardEvent) => {
    switch(e.key) {
      case 'ArrowRight':
      case 'ArrowUp':
        setValue(prev => Math.min(prev + 1, 100))
        break
      case 'ArrowLeft':
      case 'ArrowDown':
        setValue(prev => Math.max(prev - 1, 0))
        break
    }
  }

  return (
    <div
      role="slider"
      tabIndex={0}
      aria-valuemin={0}
      aria-valuemax={100}
      aria-valuenow={value}
      onKeyDown={handleKeyDown}
      className="slider"
    >
      <div
        className="slider-thumb"
        style={{ left: `${value}%` }}
      />
    </div>
  )
}

