// 1. 기본적인 단축키 구현
const ShortcutExample = () => {
  useEffect(() => {
    const handleKeyPress = (e: KeyboardEvent) => {
      // Alt + S: 저장
      if (e.altKey && e.key === 's') {
        e.preventDefault()
        // 저장 기능 실행
      }
      // Alt + H: 홈으로 이동
      if (e.altKey && e.key === 'h') {
        e.preventDefault()
        // 홈 이동
      }
    }

    window.addEventListener('keydown', handleKeyPress)
    return () => window.removeEventListener('keydown', handleKeyPress)
  }, [])

  return (
    <div>
      <button aria-keyshortcuts="Alt+S">
        저장 (Alt + S)
      </button>
      <a href="/" aria-keyshortcuts="Alt+H">
        홈으로 (Alt + H)
      </a>
    </div>
  )
}

// 2. 단축키 관리자
const useShortcuts = () => {
  useEffect(() => {
    const shortcuts = {
      's': () => console.log('저장'),
      'n': () => console.log('새로 만들기'),
      'f': () => console.log('찾기')
    }

    const handleKeyPress = (e: KeyboardEvent) => {
      if (e.altKey && shortcuts[e.key]) {
        e.preventDefault()
        shortcuts[e.key]()
      }
    }

    window.addEventListener('keydown', handleKeyPress)
    return () => window.removeEventListener('keydown', handleKeyPress)
  }, [])
}

// 3. 단축키 도움말
const ShortcutHelp = () => {
  const shortcuts = [
    { key: 'Alt + S', description: '저장' },
    { key: 'Alt + N', description: '새로 만들기' },
    { key: 'Alt + F', description: '찾기' }
  ]

  return (
    <div role="dialog" aria-label="키보드 단축키 도움말">
      <h2>키보드 단축키</h2>
      <dl>
        {shortcuts.map(({key, description}) => (
          <React.Fragment key={key}>
            <dt>{key}</dt>
            <dd>{description}</dd>
          </React.Fragment>
        ))}
      </dl>
    </div>
  )
}

