// 1. 기본적인 타이머 컴포넌트
const Timer = () => {
  const [time, setTime] = useState(300) // 5분
  const [isPaused, setIsPaused] = useState(false)

  useEffect(() => {
    if (!isPaused && time > 0) {
      const timer = setInterval(() => {
        setTime(prev => prev - 1)
      }, 1000)

      return () => clearInterval(timer)
    }
  }, [time, isPaused])

  return (
    <div role="timer" aria-live="polite">
      <p>남은 시간: {Math.floor(time / 60)}:{(time % 60).toString().padStart(2, '0')}</p>
      <button onClick={() => setIsPaused(!isPaused)}>
        {isPaused ? '계속하기' : '일시정지'}
      </button>
      <button onClick={() => setTime(prev => prev + 300)}>
        5분 연장
      </button>
    </div>
  )
}

// 2. 자동 로그아웃 경고
const AutoLogout = () => {
  const [showWarning, setShowWarning] = useState(false)
  const [timeLeft, setTimeLeft] = useState(60) // 60초

  useEffect(() => {
    if (showWarning && timeLeft > 0) {
      const timer = setInterval(() => {
        setTimeLeft(prev => prev - 1)
      }, 1000)

      return () => clearInterval(timer)
    }
  }, [showWarning, timeLeft])

  const extendSession = () => {
    setShowWarning(false)
    setTimeLeft(60)
    // 세션 연장 로직
  }

  return (
    <>
      {showWarning && (
        <div
          role="alert"
          aria-live="assertive"
          className="warning-modal"
        >
          <p>
            {timeLeft}초 후에 자동 로그아웃됩니다.
          </p>
          <button onClick={extendSession}>
            로그인 연장
          </button>
        </div>
      )}
    </>
  )
}

// 3. 슬라이드쇼 컨트롤
const Slideshow = ({ images }) => {
  const [currentIndex, setCurrentIndex] = useState(0)
  const [isPaused, setIsPaused] = useState(false)
  const [duration, setDuration] = useState(5) // 5초

  useEffect(() => {
    if (!isPaused) {
      const timer = setInterval(() => {
        setCurrentIndex(prev =>
          prev === images.length - 1 ? 0 : prev + 1
        )
      }, duration * 1000)

      return () => clearInterval(timer)
    }
  }, [isPaused, duration, images.length])

  return (
    <div role="region" aria-label="슬라이드쇼">
      <img
        src={images[currentIndex]}
        alt={`슬라이드 ${currentIndex + 1}`}
      />
      <div className="controls">
        <button onClick={() => setIsPaused(!isPaused)}>
          {isPaused ? '재생' : '일시정지'}
        </button>
        <select
          value={duration}
          onChange={(e) => setDuration(Number(e.target.value))}
          aria-label="슬라이드 전환 시간"
        >
          <option value="3">3초</option>
          <option value="5">5초</option>
          <option value="7">7초</option>
        </select>
      </div>
    </div>
  )
}

