const SafeAnimation = () => {
  const [isAnimating, setIsAnimating] = useState(false)

  return (
    <div className={`safe-animation ${isAnimating ? 'animate' : ''}`}>
      <button
        onClick={() => setIsAnimating(!isAnimating)}
        aria-pressed={isAnimating}
      >
        애니메이션 {isAnimating ? '중지' : '시작'}
      </button>
    </div>
  )
}

// CSS - 안전한 애니메이션
.safe-animation {
  /* 부드러운 트랜지션 사용 */
  transition: opacity 0.5s ease-in-out;
}

.animate {
  /* 천천히 깜빡이는 효과 (3Hz 미만) */
  animation: safeFlash 2s ease-in-out;
}

@keyframes safeFlash {
  0% { opacity: 1; }
  50% { opacity: 0.7; }
  100% { opacity: 1; }
}

// 2. 사용자 설정을 고려한 애니메이션
const AnimatedContent = ({ reducedMotion = false }) => {
  // reducedMotion: 사용자의 'prefers-reduced-motion' 설정
  const animationClass = reducedMotion ? 'no-animation' : 'safe-animation'

  return (
    <div className={animationClass}>
      콘텐츠
    </div>
  )
}

// CSS - 모션 감소 설정 반영
@media (prefers-reduced-motion: reduce) {
  .safe-animation {
    animation: none;
    transition: none;
  }
}

// 3. 경고 메시지 컴포넌트
const AlertMessage = () => {
  return (
    <div className="alert">
      {/* 깜빡임 대신 부드러운 배경색 변화 */}
      중요 알림
    </div>
  )
}

// CSS - 안전한 강조 효과
.alert {
  background: #fff3cd;
  border: 1px solid #ffeeba;
  /* 부드러운 배경색 변화 */
  transition: background-color 0.5s ease;
}

.alert:hover {
  background: #ffe8b3;
}

